llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Niraparib, a heteroaromatic oral drug with a basic amine and high molecular weight, has an absolute oral bioavailability of approximately 73% in humans, showing that basic nitrogen-containing heteroaromatic drugs can achieve high F despite ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Trametinib, an oral kinase inhibitor with multiple hydrogen-bond acceptors and aromatic heterocycles, has a mean absolute bioavailability of 72%, supporting high oral bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Risdiplam, which contains a piperazine-like amine and fused heteroaromatic system, has high oral bioavailability due to complete absorption and negligible first-pass extraction, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Tacrolimus, the closest structural analogue by Morgan similarity, has an oral bioavailability of approximately 20–25%, which is at or above the F≥20% threshold and therefore supports a high prediction, though with a narrow margin.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The physicochemical prior predicts low bioavailability due to low neutral fraction and high polar surface area, but the experimental evidence from structurally related oral drugs with basic amines and heteroaromatic cores consistently shows high absolute oral bioavailability (57–98%). The query's piperazine-containing kinase-inhibitor-like scaffold aligns with these high-F analogues, so the prediction is high (F≥20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "Morgan similarity scores to evidence molecules are low, limiting transferability.",
    "No data on efflux transport, active uptake, or metabolic stability for the query are available.",
    "The physicochemical prior suggests an absorption liability, but experimental analogues indicate that such liabilities do not necessarily preclude high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

